(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.InfinityLesson,num=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function fmt(x){if(Math.abs(x)>=1000000){const [m,e]=x.toExponential(4).split('e');return String.raw`${Number(m).toString().replace('.','{,}')}\times10^{${Number(e)}}`;}return String(Number(x.toFixed(8))).replace('.','{,}');}
const nearForms={reciprocal:String.raw`f(x)=\frac1{x-1}`,square:String.raw`f(x)=\frac1{(x-1)^2}`,hole:String.raw`f(x)=\frac{x^2-1}{x-1},\quad x\ne1`},farForms={ratio:String.raw`f(x)=\frac{2x^2+3}{x^2+1}`,reciprocal:String.raw`f(x)=\frac1x`,square:String.raw`f(x)=x^2`,cube:String.raw`f(x)=x^3`,radical:String.raw`f(x)=\frac{\sqrt{x^2+1}}x`};
let grid='';for(let x=-1;x<=3;x++){const p=core.point(x,0);grid+=`<line x1="${p.x}" x2="${p.x}" y1="30" y2="310" class="${x===0?'wave-axis':'wave-grid-line'}"/><text x="${p.x}" y="332" text-anchor="middle" class="wave-grid-label">${x}</text>`;}for(let y=-12;y<=12;y+=4){const p=core.point(0,y);grid+=`<line x1="50" x2="610" y1="${p.y}" y2="${p.y}" class="${y===0?'wave-axis':'wave-grid-line'}"/><text x="42" y="${p.y+5}" text-anchor="end" class="wave-grid-label">${y}</text>`;}$('#near-grid').innerHTML=grid;
function drawNear(){const kind=$('#near-kind').value,d=core.distances[Number($('#near-step').value)],t=core.near(kind,d);$('#near-output').value=String(d).replace('.',',');$('#near-step').setAttribute('aria-valuetext',String(d));math($('#near-formula'),nearForms[kind]);for(const side of ['left','right'])$('#near-'+side+'-curve').setAttribute('d',core.nearCurve(kind,side).map((p,i)=>`${i?'L':'M'}${p.x} ${p.y}`).join(' '));let hidden=0;for(const [id,x,y]of [['near-left-point',t.leftX,t.leftY],['near-right-point',t.rightX,t.rightY]]){const p=core.point(x,y);$('#'+id).setAttribute('cx',p.x);$('#'+id).setAttribute('cy',p.y);const visible=Math.abs(y)<=12;$('#'+id).setAttribute('visibility',visible?'visible':'hidden');if(!visible)hidden++;}const p=core.point(1,2);$('#near-hole').innerHTML=kind==='hole'?`<circle cx="${p.x}" cy="${p.y}" r="5" class="infinity-hole"/>`:'';math($('#near-values'),String.raw`\begin{aligned}f(${fmt(t.leftX)})&\approx${fmt(t.leftY)}\\f(${fmt(t.rightX)})&\approx${fmt(t.rightY)}\\f(1)&\text{ tidak terdefinisi}\end{aligned}`);const left=kind==='hole'?'2':kind==='square'?String.raw`+\infty`:String.raw`-\infty`,right=kind==='hole'?'2':String.raw`+\infty`;math($('#near-limits'),String.raw`\begin{aligned}\lim_{x\to1^-}f(x)&=${left}\\\lim_{x\to1^+}f(x)&=${right}\\\lim_{x\to1}f(x)&`+(kind==='reciprocal'?String.raw`\text{ tidak ada}`:'='+right)+String.raw`\end{aligned}`);$('#near-note').textContent=(hidden?`Kedua titik terpilih berada di luar jendela keluaran. Nilai sebenarnya tetap ditampilkan di atas. `:'Titik terpilih masih berada dalam jendela keluaran. ')+(kind==='hole'?'Kedua sisi mendekati dua. Ini lubang, bukan asimtot tegak.':kind==='square'?'Kedua sisi membesar positif tanpa batas. Limit tak hingga positif tidak berarti fungsi memiliki nilai real di masukan satu.':'Dari kiri keluaran turun tanpa batas, dari kanan membesar positif tanpa batas. Limit dua sisi tidak dapat ditulis sama dengan positif tak hingga.');$('#near-plot').setAttribute('aria-label',`Grafik ${kind==='hole'?'pecahan dengan lubang':kind==='square'?'satu dibagi kuadrat selisih x dan satu':'satu dibagi x dikurangi satu'}. Jarak dari satu ${d}. Keluaran kiri ${t.leftY}, kanan ${t.rightY}. ${hidden?'Titik terpilih berada di luar jendela grafik.':''} ${kind==='hole'?'Limit dua sisi dua.':kind==='square'?'Kedua sisi menuju positif tak hingga.':'Kiri menuju negatif tak hingga, kanan positif tak hingga.'}`);}
for(const id of ['near-kind','near-step'])$('#'+id).addEventListener('input',drawNear);drawNear();
function drawFar(){const kind=$('#far-kind').value,index=Number($('#far-step').value),R=core.radii[index],left=core.farValue(kind,-R),right=core.farValue(kind,R);$('#far-output').value=R;$('#far-step').setAttribute('aria-valuetext',String(R));math($('#far-formula'),farForms[kind]);$('#far-table').innerHTML=core.radii.map((r,i)=>`<tr ${i===index?'class="infinity-selected"':''}>${[-r,core.farValue(kind,-r),r,core.farValue(kind,r)].map(v=>`<td><span data-tex="${fmt(v)}"></span></td>`).join('')}</tr>`).join('');math($('#far-values'),String.raw`\begin{aligned}f(-${R})&\approx${fmt(left)}\\f(${R})&\approx${fmt(right)}\end{aligned}`);const limits={ratio:['2','2'],reciprocal:['0','0'],square:[String.raw`+\infty`,String.raw`+\infty`],cube:[String.raw`-\infty`,String.raw`+\infty`],radical:['-1','1']}[kind];math($('#far-limits'),String.raw`\begin{aligned}\lim_{x\to-\infty}f(x)&=${limits[0]}\\\lim_{x\to+\infty}f(x)&=${limits[1]}\end{aligned}`);$('#far-note').textContent=({ratio:'Membagi pembilang dan penyebut dengan kuadrat masukan menunjukkan kedua arah mendekati dua. Garis y sama dengan dua adalah asimtot mendatar.',reciprocal:'Di kiri jauh nilai mendekati nol dari sisi negatif; di kanan jauh dari sisi positif. Limit keduanya nol, tanpa pernah memasukkan tak hingga sebagai bilangan.',square:'Kuadrat masukan negatif maupun positif tetap positif. Kedua arah membesar positif tanpa batas.',cube:'Pangkat ganjil mempertahankan tanda: arah negatif turun tanpa batas, arah positif membesar tanpa batas.',radical:'Akar kuadrat selalu tidak negatif, tetapi pembaginya bertanda. Arah negatif mendekati negatif satu; arah positif mendekati satu.'})[kind]+' Tabel dibulatkan hingga delapan angka di belakang koma; angka yang tampak sama belum tentu nilai tepatnya sama.';}
for(const id of ['far-kind','far-step'])$('#'+id).addEventListener('input',drawFar);drawFar();
const questions=[{tex:String.raw`\lim_{x\to+\infty}\frac{2x^2+3}{x^2+1}`,prompt:'Berapa hasil limit berhingga ini?',n:2,d:1,hint:'Bagi pembilang dan penyebut dengan x kuadrat.',why:'Bentuknya menjadi dua ditambah tiga per x kuadrat, dibagi satu ditambah satu per x kuadrat. Limitnya dua.'},{tex:String.raw`\lim_{x\to-\infty}\frac1x`,prompt:'Berapa hasil limit berhingga ini?',n:0,d:1,hint:'Nilainya negatif tetapi besarnya makin kecil saat nilai mutlak masukan membesar.',why:'Keluaran mendekati nol dari sisi negatif. Nilai limitnya tetap nol.'},{tex:String.raw`\lim_{x\to-\infty}\frac{\sqrt{x^2+1}}x`,prompt:'Berapa hasil limit berhingga ini?',n:-1,d:1,hint:'Akar x kuadrat adalah nilai mutlak x, bukan selalu x.',why:'Faktor nilai mutlak x dibagi x adalah negatif satu di arah negatif. Faktor akar dari satu ditambah satu per x kuadrat mendekati satu, sehingga hasilnya negatif satu.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis nilai limit berhingga sebagai bilangan, misalnya 2 atau -1.':'Belum tepat. Periksa arah pendekatan, pangkat tertinggi, dan tanda faktor.');}));
const choices=[{tex:String.raw`\lim_{x\to1}\frac1{x-1}`,prompt:'Apa kesimpulan dari kedua sisi?',options:[{text:'Positif tak hingga dari kedua sisi.'},{text:'Kiri negatif tak hingga dan kanan positif tak hingga; limit dua sisi tidak ada.'},{text:'Nol, rata-rata dari kedua arah.'}],answer:1,why:'Penyebut kecil bertanda negatif di kiri dan positif di kanan. Kedua arah tidak mempunyai perilaku tak hingga yang sama.'},{tex:String.raw`\lim_{x\to1}\frac1{(x-1)^2}`,prompt:'Apa perilaku keluarannya?',options:[{text:'Kedua sisi menuju positif tak hingga.'},{text:'Kiri negatif tak hingga, kanan positif tak hingga.'},{text:'Limitnya nol karena penyebut mendekati nol.'}],answer:0,why:'Penyebut yang dikuadratkan positif dan mendekati nol dari kedua sisi. Kebalikannya membesar positif tanpa batas.'},{tex:String.raw`f(x)=\frac{x^2-1}{x-1}`,prompt:'Apakah garis x sama dengan satu merupakan asimtot tegak?',options:[{text:'Ya, setiap penyebut nol pasti asimtot tegak.'},{text:'Ya, karena nilai fungsi di satu tidak terdefinisi.'},{text:'Tidak. Setelah faktorisasi, limitnya dua; titik itu merupakan lubang.'}],answer:2,why:'Untuk masukan bukan satu, pecahan sama dengan x ditambah satu. Nilai di sekitar satu mendekati dua, sehingga tidak ada pertumbuhan tanpa batas di titik tersebut.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}" ${o.label?'aria-label="'+o.label+'"':''}>${o.tex?'<span data-tex="'+o.tex+'"></span>':o.text}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-infinity-limits-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-infinity-limits-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();